style.css:
@-moz-document domain("claude.ai") {
/* Style for the user input area (where you type) */
  textarea, 
  input[type="text"] {
    font-family: 'Courier New', Courier, monospace !important;
  }

  /* Style for the user's chat messages */
  .user-message-class, /* Adjust this selector as needed */
  .chat-message-user {
    font-family: 'Courier New', Courier, monospace !important;
  }

  /* Optional: Add monospaced font to other relevant areas */
  .chat-input-container, 
  .message-input, 
  .input-field {
    font-family: 'Courier New', Courier, monospace !important;
  }
}
